import React, { useState, useEffect, useCallback } from 'react';
import axios from 'axios';
import { useModal } from '../../context/ModalContext';
import './AdminOrders.css';

const AdminOrders = ({ apiBase }) => {
  const { showModal } = useModal();
  const [orders, setOrders] = useState([]);
  const [loading, setLoading] = useState(false);

  const token = localStorage.getItem('auth-token');

  const fetchOrders = useCallback(async () => {
    try {
      setLoading(true);
      const response = await axios.get(`${apiBase}/api/admin/orders`, {
        headers: { 'auth-token': token },
      });
      setOrders(response.data.orders);
    } catch (error) {
      console.error('Error fetching orders:', error);
      showModal({ title: 'Error', message: 'Failed to fetch orders' });
    } finally {
      setLoading(false);
    }
  }, [apiBase, token, showModal]);

  useEffect(() => {
    fetchOrders();
  }, [fetchOrders]);

  const handleUpdateStatus = async (orderId, newStatus) => {
    try {
      await axios.put(
        `${apiBase}/api/admin/orders/${orderId}`,
        { status: newStatus },
        { headers: { 'auth-token': token } }
      );
      showModal({ title: 'Success', message: 'Order status updated' });
      fetchOrders();
    } catch (error) {
      console.error('Error updating order:', error);
      showModal({ title: 'Error', message: 'Failed to update order' });
    }
  };

  const getStatusColor = (status) => {
    switch (status) {
      case 'Order Placed':
      case 'pending':
        return '#ff9800';
      case 'Processing':
      case 'processing':
        return '#2196f3';
      case 'Shipped':
        return '#9c27b0';
      case 'Out for Delivery':
        return '#673ab7';
      case 'Completed':
      case 'completed':
      case 'Delivered':
        return '#4caf50';
      case 'cancelled':
        return '#f44336';
      default:
        return '#666';
    }
  };

  return (
    <div className="admin-orders">
      <h2>Manage Orders</h2>

      {loading ? (
        <p>Loading orders...</p>
      ) : (
        <div className="orders-table">
          <table>
            <thead>
              <tr>
                <th>Order ID</th>
                <th>User ID</th>
                <th>Total Amount</th>
                <th>Status</th>
                <th>Date</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {orders.map((order) => (
                <tr key={order._id}>
                  <td>{order._id}</td>
                  <td>{order.userId}</td>
                  <td>₹{order.totalAmount}</td>
                  <td style={{ color: getStatusColor(order.status) }}>
                    {order.status.charAt(0).toUpperCase() + order.status.slice(1)}
                  </td>
                  <td>{new Date(order.createdAt).toLocaleDateString()}</td>
                  <td className="actions">
                    <select
                      className="status-select"
                      value={order.status}
                      onChange={(e) => handleUpdateStatus(order._id, e.target.value)}
                    >
                      <option value="Order Placed">Order Placed</option>
                      <option value="Processing">Processing</option>
                      <option value="Shipped">Shipped</option>
                      <option value="Out for Delivery">Out for Delivery</option>
                      <option value="Delivered">Delivered</option>
                      <option value="cancelled">Cancelled</option>
                    </select>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {orders.length === 0 && !loading && (
        <p className="no-orders">No orders found</p>
      )}
    </div>
  );
};

export default AdminOrders;
